// Greet 返回一句问候。name 为空白时用 "world"。
func Greet(name string) string {
	if strings.TrimSpace(name) == "" {
		name = "world"
	}
	return "Hello, " + name + "!"
}

// Slug 把文本转成小写、以单个连字符连接的分段标识。
// 首尾空白被去掉，连续空白折成一个连字符。
func Slug(s string) string {
	return strings.ToLower(strings.Join(strings.Fields(s), "-"))
}
